134	        return Fetch::ResponseType::ARRAYBUFFER;
135	    } else if (!strcmp(type, Fetch::response_type[Fetch::ResponseType::FILE])) {
136	        return Fetch::ResponseType::FILE;
137	    } else if (!strcmp(type, Fetch::response_type[Fetch::ResponseType::JSON])) {
138	        return Fetch::ResponseType::JSON;
139	    } else if (!strcmp(type, Fetch::response_type[Fetch::ResponseType::TXT])) {
