146	Fetch::ContentType get_content_type(const char* type)
147	{
148	    // Note: type may be in the format "application/json; charset=utf-8"
149	    char buf[128] = { 0 };
150	    const char* semicolon = strchr(type, ';');
151	    if (semicolon) {
152	        size_t len = semicolon - type;
153	        if (len >= sizeof(buf))
154	            len = sizeof(buf) - 1;
155	        strncpy(buf, type, len);
156	        buf[len] = '\0';
157	    } else {
158	        strncpy(buf, type, sizeof(buf) - 1);
159	        buf[sizeof(buf) - 1] = '\0';
160	    }
161	
162	    if (!strcmp(buf, Fetch::content_type[Fetch::ContentType::STREAM])) {
163	        return Fetch::ContentType::STREAM;
164	    } else if (!strcmp(buf, Fetch::content_type[Fetch::ContentType::TEXT])) {
165	        return Fetch::ContentType::TEXT;
166	    } else if (!strcmp(buf, Fetch::content_type[Fetch::ContentType::URLENCODED])) {
167	        return Fetch::ContentType::URLENCODED;
168	    } else if (!strcmp(buf, Fetch::content_type[Fetch::ContentType::JSON_CT])) {
169	        return Fetch::ContentType::JSON_CT;
170	    } else {
171	        return (Fetch::ContentType)0;
172	    }
173	}
