242	bool get_method(FtString method, Fetch::MethodType* out)
243	{
244	    FETCH_DEBUG("len:%d method:%s", strlen(method), method);
245	    if (!out) {
246	        return false;
247	    }
248	    if (!check_str(method)) {
249	        *out = Fetch::MethodType::GET;
250	        return true;
251	    }
252	
253	    *out = (Fetch::MethodType)type_contain(
254	        Fetch::method_type, arrayof(Fetch::method_type), method, true);
255	    if (*out) {
256	        return true;
257	    }
258	    return false;
259	}
