307	static Fetch::ResponseType get_cy_from_response(std::map<std::string, std::string>& headers)
308	{
309	    auto it = headers.find("content-type");
310	    if (it == headers.end())
311	        it = headers.find("Content-Type");
312	    if (it == headers.end())
313	        return Fetch::ResponseType::TXT;
314	    std::string content_type = it->second;
315	    size_t semicomma = content_type.find(';');
316	    if (semicomma != std::string::npos) {
317	        content_type = content_type.substr(0, semicomma);
318	    }
319	    if (content_type == "application/json") {
320	        return Fetch::ResponseType::JSON;
321	    } else {
322	        return Fetch::ResponseType::TXT;
323	    }
324	}
