524	bool get_post_data_cb(const cJSON* const item, void* userp)
525	{
526	    std::string* out_str = static_cast<std::string*>(userp);
527	
528	    ASSERT_RET_NULL(out_str);
529	
530	    if (!out_str->empty()) {
531	        out_str->append("&");
532	    }
533	    out_str->append(item->string);
534	    out_str->append("=");
535	
536	    char valuestr[24] = { '\0' };
537	    switch (item->type) {
538	    case cJSON_Number:
539	        sprintf(valuestr, "%lld", item->valueint);
540	        out_str->append(std::string(valuestr));
541	        break;
542	    case cJSON_String:
543	        out_str->append(item->valuestring);
544	        break;
545	    case cJSON_False:
546	        out_str->append("false");
547	        break;
548	    case cJSON_True:
549	        out_str->append("true");
