559	// Need to release  out->data
560	bool get_pdata_and_content_type(ft_context_ref ft_ctx, FtAny data,
561	    Fetch::ContentType ct, content_t* out)
562	{
563	    ft_type data_type = ft_get_type(ft_ctx, *data);
564	    FETCH_DEBUG("data: %d!", data_type);
565	    switch (data_type) {
566	    // ArrayBuffer type
567	    case FT_TYPE_BUFFER:
568	    case FT_TYPE_TYPED_BUFFER:
569	        out->content_type = ct ? ct : Fetch::ContentType::STREAM;
570	        out->buf_type_data = ft_to_buffer(ft_ctx, &out->size, *data);
571	        return true;
572	
573	    // no set
574	    case FT_TYPE_NULL:
575	    case FT_TYPE_UNDEF:
576	    case FT_TYPE_NONE:
577	        out->content_type = ct ? ct : Fetch::ContentType::TEXT;
578	        return true;
579	
580	    // string type
581	    case FT_TYPE_STRING:
582	        out->content_type = ct ? ct : Fetch::ContentType::TEXT;
583	        break;
584	
585	    // json type
586	    case FT_TYPE_OBJECT:
587	        if (ct && ct != Fetch::ContentType::URLENCODED) {
588	            out->content_type = ct;
589	            break;
590	        }
591	        out->content_type = Fetch::ContentType::URLENCODED;
592	
593	        if (!ft_map_for_every_entry(ft_ctx, data, (void*)&out->data,
594	                get_post_data_cb)) {
595	            return false;
596	        }
597	        out->size = out->data.size();
598	        FETCH_DEBUG("contenttype data:%s", out->data.c_str());
599	        return true;
600	    default:
601	        return false;
602	    }
603	    const char* ft_data = ft_to_string(ft_ctx, *data);
604	    out->data.assign(ft_data);
605	    out->size = out->data.size();
606	    ft_free_string(ft_ctx, ft_data);
607	    return true;
608	}
