231	static void __request_cb(int state, uv_response_t* response)
232	{
233	    REQUEST_DEBUG("in __request_cb, state = %d", state);
234	    ReqInfo* info = static_cast<ReqInfo*>(response->userp);
235	    if (!info)
236	        return;
237	    FeatureInstanceHandle feature = info->feature_handle;
238	    if (!FeatureInstanceIsDetached(feature)) {
239	        RequestContext* th = getRequestContext(feature);
240	        if (info->share == false) {
241	            th->shareInfo = NULL;
242	        }
243	
244	        DownloadResult* res = static_cast<DownloadResult*>(malloc(sizeof(DownloadResult)));
245	        if (state == UV_REQUEST_DONE) {
246	            if (info->request_type == UV_DOWNLOAD) {
247	                char* body = app_absolute_to_relative_path(th->pkg_name, response->body);
248	                // 返回文件绝对地址
249	                system_request_dl_cmpl_succ_t* param = system_requestMallocdl_cmpl_succ_t();
250	                char* value = (char*)FeatureMalloc(strlen(body) + 1, FT_CHAR);
251	                sprintf(value, "%s", body);
252	                param->uri = value;
253	                INVOKE_SUCCESS_CB(info->success, param);
254	                FeatureFreeValue(param);
255	
256	                res->success = true;
257	                res->data = body;
258	                res->code = UV_REQUEST_DONE;
259	            }
260	            InspectHostNetResponse(info->request, response, InspectHostNetGetCurrentReqId(), response->headers);
261	
262	        } else if (state == UV_REQUEST_ERROR) {
263	            // body内存的是绝对路径的file位置
264	            REQUEST_ERROR("request error: %s", response->body);
265	            INVOKE_FAIL_CB(info->fail, response->body, FT_ERR_TASK_FAILED);
266	            res->success = false;
267	            res->data = strdup(response->body);
268	            res->code = FT_ERR_TASK_FAILED;
269	        } else if (state == REQUEST_CANCEL) {
270	            INVOKE_FAIL_CB(info->fail, "user cancel request", state);
271	            res->success = false;
272	            res->data = strdup(response->body);
273	            res->code = FT_ERR_CANCEL_ERROR_CODE;
274	        }
275	        addResult(feature, info->uuid, res);
276	        INVOKE_COMPLET_CB(info->complete);
277	        REMOVE_ALL_CALLBACK(info->success, info->fail, info->complete);
278	    } else {
279	        REQUEST_DEBUG("feature instance is detached");
280	    }
281	
282	    weakref_list_delete(&info->node);
283	    freeReqInfo(info);
284	}
