286	int __progress_cb(uv_request_t* request, off_t dltotal, off_t dlnow, off_t ultotal, off_t ulnow)
287	{
288	    // REQUEST_DEBUG("=== in __progress_cb, total = %ld, now = %ld", dltotal, dlnow);
