335	// 校验 URI 是否合法：必须以 http:// 或 https:// 开头，且不含空白字符。
336	// 原实现使用 std::regex("^https?://[\\S]*$") 进行匹配，语义等价，
337	// 但 std::regex 内部基于回溯的 NFA 引擎在处理长 URL 时会产生大量栈递归，
338	// 在 NuttX 等栈空间有限的嵌入式环境下容易导致栈溢出（stack overflow）。
339	// 改用简单的字符串遍历，栈开销几乎为零。
340	bool __is_valid_uri(const char* uri)
341	{
342	    if (uri == NULL)
343	        return false;
344	
345	    // 检查协议头：http:// 或 https://
346	    if (strncmp(uri, "https://", 8) == 0) {
347	        uri += 8;
348	    } else if (strncmp(uri, "http://", 7) == 0) {
349	        uri += 7;
350	    } else {
351	        return false;
352	    }
353	
354	    // 协议头后面必须有内容，且不能包含空白字符
355	    if (*uri == '\0')
356	        return false;
357	    for (const char* p = uri; *p != '\0'; ++p) {
358	        if (isspace((unsigned char)*p))
359	            return false;
360	    }
361	    return true;
362	}
