373	char* __get_filename_from_url(const char* url)
374	{
375	    const char* question_mark = strrchr(url, '?');
376	
377	    // remove url parameter
378	    char* url_main;
379	    if (question_mark == NULL) {
380	        url_main = strdup(url);
381	    } else {
382	        url_main = strndup(url, question_mark - url - 1);
383	    }
384	    // remove slash mark in backwards
385	    __remove_trailing_slash(url_main);
386	    REQUEST_DEBUG("url_main = %s", url_main);
387	
388	    // get last slash mark in url_main
389	    const char* slash_mark = strrchr(url_main, '/');
390	
391	    if (slash_mark != NULL) {
392	        char* filename = strdup(slash_mark + 1);
393	        REQUEST_DEBUG("tmp filename = %s", filename);
394	        const char* dot_mask = strrchr(filename, '.');
395	        if (dot_mask != NULL && dot_mask == strchr(filename, '.')) {
396	            // only one dot in filename, its a valid filename
397	            free(url_main);
398	            return filename;
399	        }
400	        free(filename);
401	    }
402	    free(url_main);
403	
404	    REQUEST_DEBUG("genarate default filename");
405	    // cannot get filename from url, create one
406	    char tmp[64] = "";
407	    sprintf(tmp, "%s-%d.%s", DEFAULT_FILE_NAME, rand(), DEFAULT_FILE_TYPE);
408	    return strdup(tmp);
409	}
