411	void system_request_wrap_download(FeatureInstanceHandle feature, AppendData append_data, system_request_download_t* param)
412	{
413	    const char* msg;
414	    char *filename, *token, *header;
415	    int code;
416	    system_request_download_succ_t* suc_param;
417	    RequestContext* th = getRequestContext(feature);
418	    ft_context_ref ft_ctx = FeatureGetContext(feature);
419	    std::map<std::string, std::string> formdata;
420	
421	    ReqInfo* info = static_cast<ReqInfo*>(malloc(sizeof(ReqInfo)));
422	    if (!info) {
423	        REQUEST_ERROR("malloc fail");
424	        code = FT_ERR_GENERAL;
425	        msg = "malloc fail";
426	        goto callFail;
427	    }
428	    initInfo(info);
429	
430	    if (param->share == false) {
431	        info->share = false;
432	        if (th->shareInfo != NULL) {
433	            __request_cancel(th->shareInfo);
434	        }
435	        th->shareInfo = info;
436	    }
437	
438	    // 参数检查
439	    // REQUEST_DEBUG("get url = %s", param->url);
440	    if (!check_str(param->url) || !__is_valid_uri(param->url)) {
441	        code = FT_ERR_ARGS;
442	        msg = "invalid url";
443	        goto callFail;
444	    }
445	
446	    info->request_type = UV_DOWNLOAD;
447	    info->feature_handle = FeatureDupInstanceHandle(feature);
448	
449	    if (check_str(param->filename)) {
450	        filename = strdup(param->filename);
451	    } else {
452	        filename = __get_filename_from_url(param->url);
453	    }
454	    // REQUEST_DEBUG("filename = %s", filename);
455	
456	    info->filename = app_relative_to_absolute_path(th->pkg_name, filename);
457	    if (!info->filename) {
458	        info->filename = app_absolute_path_generator(th->pkg_name, "files", filename);
459	        if (!info->filename) {
460	            REQUEST_ERROR("info->filename is null");
461	        }
462	    }
463	    free(filename);
464	    REQUEST_DEBUG("info->filename = %s", info->filename);
465	
466	    if (!check_disk_limit()) {
467	        // TODO cannot call at this place!
468	        // notify_disk_space_insufficient(feature, param->url);
469	        REQUEST_ERROR("insufficient memory to download file");
470	        code = FT_ERR_GENERAL;
471	        msg = "no space to download file";
472	        goto callFail;
473	    }
474	
475	    uv_request_create(&info->request);
476	    uv_request_set_url(info->request, param->url);
477	    uv_request_set_method(info->request, "GET");
478	    uv_request_set_atrribute(info->request, info->request_type, (void*)info->filename);
479	    if (FeatureCheckCallbackId(feature, param->onDownLoadNotify)) {
480	        info->notify_func = param->onDownLoadNotify;
481	        uv_request_set_atrribute(info->request, UV_DOWNLOAD_PROGRESS, (void*)__progress_cb);
482	    }
483	
484	    if (check_str(param->header)) {
485	        // header format "{"test":"abc","test2":"ddd"}"
486	        header = strdup(param->header);
487	        ft_value_t ft_header = ft_form_headers(ft_ctx, header);
488	        if (check_header(ft_ctx, &ft_header, formdata)) {
489	            for (auto [key, val] : formdata) {
490	                REQUEST_DEBUG("formdata: %s", std::string(key + ":" + val).c_str());
491	                uv_request_append_header(info->request, std::string(key + ":" + val).c_str());
492	            }
493	        }
494	        free(header);
495	        ft_free_value(ft_ctx, ft_header);
496	    }
497	
498	    uv_request_set_userp(info->request, info);
499	    InspectHostNetRequest(info->request, "GET", InspectHostNetGetReqId());
500	    uv_request_commit(th->handle, info->request, __request_cb);
501	    weakref_list_initialize(&info->node);
502	    weakref_list_add_tail(&th->linklist, &info->node);
503	
504	    suc_param = system_requestMallocdownload_succ_t();
505	    info->uuid = uuid();
506	    token = (char*)FeatureMalloc(strlen(info->uuid) + 1, FT_CHAR);
507	    sprintf(token, "%s", info->uuid);
508	    suc_param->token = token;
509	    // REQUEST_DEBUG("suc_param._token = %s, info = %p", suc_param->token, info);
510	    INVOKE_SUCCESS_CB(param->success, suc_param);
511	    INVOKE_COMPLET_CB(param->complete);
512	    REMOVE_ALL_CALLBACK(param->success, param->fail, param->complete);
513	    FeatureFreeValue(suc_param);
514	    return;
515	callFail:
516	    InspectHostNetLoadingFailed(true);
517	    REQUEST_ERROR("code = %d, msg = %s", code, msg);
518	    INVOKE_FAIL_CB(param->fail, msg, code);
519	    INVOKE_COMPLET_CB(param->complete);
520	    REMOVE_ALL_CALLBACK(param->success, param->fail, param->complete);
521	    if (info) {
522	        freeReqInfo(info);
523	    }
524	}
